mapper.select:
SELECT * FROM ( SELECT A.*, ROWNUM AS RNUM FROM ( SELECT m.id as MEETING_ID, m.title as TITLE, m.description as DESCRIPTION, m.status as STATUS, m.scheduled_at as SCHEDULED_AT, m.location as LOCATION, m.location_detail as LOCATION_DETAIL, m.agenda as AGENDA, m.created_at as CREATED_AT, m.beneficiary_id as BENEFICIARY_ID, (SELECT u.nickname FROM woorido.users u WHERE u.id = m.beneficiary_id) as BENEFICIARY_NICKNAME, (SELECT COUNT(*) FROM woorido.meeting_votes mv JOIN woorido.meeting_vote_records mvr ON mv.id = mvr.meeting_vote_id WHERE mv.meeting_id = m.id AND mvr.choice = 'AGREE') as CONFIRMED_COUNT, (SELECT COUNT(*) FROM woorido.challenge_members cm WHERE cm.challenge_id = m.challenge_id AND cm.privilege_status = 'ACTIVE') as TOTAL_MEMBERS FROM woorido.meetings m WHERE m.challenge_id = #{challengeId}
AND m.status = #{status}
ORDER BY m.scheduled_at DESC ) A WHERE ROWNUM <= (#{offset} + #{limit}) ) WHERE RNUM > #{offset}

SELECT COUNT(*)
FROM woorido.meetings
WHERE challenge_id = #{challengeId}

    AND status = #{status}
